// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(c));
        amount = bound(amount, 0, 1e24);

        // fund the contract with a fuzzed amount
        vm.deal(address(c), amount);

        uint256 ownerBefore = c.Owner().balance;
        uint256 contractBefore = address(c).balance;
        bool ok;

        vm.prank(caller);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever withdraw succeeds, it was executed by (and paid out to)
        // the recorded Owner, draining the entire contract balance to the Owner.
        assertTrue(
            !ok || (caller == c.Owner() && address(c).balance == 0
                    && c.Owner().balance == ownerBefore + contractBefore)
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount, uint256 ownerSeedBalance) public {
        // Keep the domain WIDE: any actor, any amount in a sane range.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 1e30);
        ownerSeedBalance = bound(ownerSeedBalance, 1, 1e30);

        address owner = c.Owner();

        // Fund the contract and give the recorded Owner a known balance baseline.
        vm.deal(address(c), amount);
        vm.deal(owner, ownerSeedBalance);
        uint256 ownerBefore = owner.balance;
        uint256 contractBefore = address(c).balance;

        bool ok;
        vm.prank(actor);
        try c.withdraw() { ok = true; } catch { ok = false; }

        if (ok) {
            // A successful withdraw must drain the ENTIRE balance to the recorded Owner
            // (the recipient is determined by the contract's rule, not by whoever called).
            assertTrue(
                actor == owner &&
                address(c).balance == 0 &&
                owner.balance == ownerBefore + contractBefore
            );
        } else {
            // A failed withdraw must leave all funds intact with the contract.
            assertTrue(address(c).balance == contractBefore && owner.balance == ownerBefore);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address owner, address caller, uint256 amount) public {
        vm.assume(owner != address(0));
        vm.assume(uint256(uint160(owner)) > 10); // avoid precompile / system addresses
        bound(amount, 1, 100 ether);

        // Deploy a fresh C so that the *recorded* Owner is the fuzzed `owner`,
        // independent of who later calls withdraw().
        vm.prank(owner);
        C target = new C();

        // Fund the contract so a withdraw actually moves value.
        vm.deal(address(target), amount);

        uint256 ownerBefore = owner.balance;
        uint256 callerBefore = caller.balance;
        uint256 contractBefore = address(target).balance;
        bool ok;

        vm.prank(caller);
        try target.withdraw() { ok = true; } catch { ok = false; }

        if (caller != owner) {
            // Non-owners may never withdraw successfully.
            assertTrue(!ok && address(target).balance == contractBefore);
        } else {
            // A successful withdraw must drain the ENTIRE balance to the recorded
            // Owner (c.Owner()), enriching only the Owner and leaving c empty.
            assertTrue(
                ok
                && address(target).balance == 0
                && owner.balance == ownerBefore + contractBefore
                && caller.balance == callerBefore + contractBefore
            );
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address ownerOfC;

    function setUp() public {
        // Deploy C from a distinct address so the recorded Owner differs from the test contract.
        ownerOfC = makeAddr("ownerActor");
        vm.startPrank(ownerOfC);
        c = new C();
        vm.stopPrank();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        address actor = makeAddr("actor");

        vm.deal(address(c), amount);
        uint256 ownerBefore = ownerOfC.balance;
        uint256 actorBefore = actor.balance;

        // Only the recorded Owner may withdraw; drive c through `withdraw` as the Owner.
        vm.prank(ownerOfC);
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful withdraw always pays the contract's entire balance to the
        // recorded Owner (not merely to the caller) and empties the contract.
        assertTrue(
            (ok && address(c).balance == 0 && ownerOfC.balance == ownerBefore + amount && actor.balance == actorBefore) ||
            (!ok && true),
            "withdraw must pay Owner the whole balance and leave c empty"
        );
    }
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}
    fallback() external payable {}

    function test(address adr, uint256 v) public
    {
        require(address(this).balance >= v);
        uint256 targetBefore = address(adr).balance;
        c.Command{value: v}(adr, "");
        assert(address(adr).balance == targetBefore + v);
    }
}

